#include <cstddef>
#include <string>

void receiveShipment(int stockCount, int delivered)
{
    stockCount += delivered;
}

std::size_t warehouseLabelLength(const std::string label)
{
    return label.size();
}

class WarehouseDashboard
{
public:
    WarehouseDashboard(int initialStock, std::string label)
        : stockCount_(initialStock), label_(label)
    {
    }

    void receive(int delivered)
    {
        receiveShipment(stockCount_, delivered);
    }

    std::size_t labelLength() const
    {
        return warehouseLabelLength(label_);
    }

    int stockCount() const
    {
        return stockCount_;
    }

private:
    int stockCount_;
    std::string label_;
};

